async function runtime(){const{env}=await import("cloudflare:workers");return env as any}
export async function ensureAgentControlSchema(db:any){await db.prepare("CREATE TABLE IF NOT EXISTS agent_project_controls (project_id TEXT PRIMARY KEY,agent_id TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,stop_phase_key TEXT NOT NULL DEFAULT 'reel-video-production',status TEXT NOT NULL,activated_at TEXT NOT NULL,updated_at TEXT NOT NULL,last_phase_key TEXT,last_error TEXT)").run();await db.prepare("CREATE TABLE IF NOT EXISTS agent_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL,agent_id TEXT NOT NULL,phase_key TEXT NOT NULL,status TEXT NOT NULL,formula_id TEXT,formula_version TEXT,provider TEXT,model TEXT,started_at TEXT NOT NULL,completed_at TEXT,error TEXT)").run();try{const now=new Date().toISOString(),staleBefore=new Date(Date.now()-10*60_000).toISOString();await db.prepare("UPDATE orchestrator_jobs SET status='FAILED',last_error='Agent prompt run exceeded the execution window; saved Project data was preserved and Resume Task can safely continue.',completed_at=?,updated_at=? WHERE job_type='AGENT_TASK' AND status='RUNNING' AND updated_at<?").bind(now,now,staleBefore).run();await db.prepare("UPDATE agent_project_controls SET stop_phase_key='reel-video-production' WHERE stop_phase_key='content-production'").run();await db.prepare("UPDATE agent_project_controls SET active=0,status='Needs Attention',last_error=COALESCE((SELECT j.last_error FROM orchestrator_jobs j WHERE j.project_id=agent_project_controls.project_id AND j.job_type='AGENT_TASK' AND j.actor=agent_project_controls.agent_id AND j.status='FAILED' ORDER BY j.updated_at DESC LIMIT 1),last_error),updated_at=? WHERE (status LIKE 'Agent Working%' OR status LIKE 'FrameFlow Processing%') AND EXISTS (SELECT 1 FROM orchestrator_jobs j WHERE j.project_id=agent_project_controls.project_id AND j.job_type='AGENT_TASK' AND j.actor=agent_project_controls.agent_id AND j.status='FAILED' AND j.updated_at>agent_project_controls.updated_at)").bind(now).run()}catch{}}
export async function sendTelegram(db:any,env:any,text:string){try{const telegram=await loadIntegration(db,env,"telegram");if(!telegram?.secret)return;const chatId=String(telegram.config?.chatId||"8009020714");await fetch(`https://api.telegram.org/bot${telegram.secret}/sendMessage`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({chat_id:chatId,text})})}catch(error){console.error("Telegram notification failed",{message:String((error as Error)?.message||error)})}}
export async function recoverInterruptedAgentControls(db:any){
 await ensureAgentControlSchema(db);
 const now=new Date().toISOString(),staleBefore=new Date(Date.now()-2*60_000).toISOString();
 await db.prepare("UPDATE agent_project_controls SET active=0,status='Needs Attention · Resume interrupted Agent task',last_error='The previous request ended before an Agent job was created. Resume Task can safely continue from the saved phase.',updated_at=? WHERE active=1 AND status LIKE 'Agent Working%' AND updated_at<? AND NOT EXISTS (SELECT 1 FROM orchestrator_jobs j WHERE j.project_id=agent_project_controls.project_id AND j.job_type='AGENT_TASK' AND j.status IN ('QUEUED','RUNNING','WAITING_PROVIDER','RETRY_PENDING'))").bind(now,staleBefore).run();
}
export async function activateAgent(db:any,projectId:string){await ensureAgentControlSchema(db);const now=new Date().toISOString();await db.prepare("INSERT INTO agent_project_controls(project_id,agent_id,active,stop_phase_key,status,activated_at,updated_at,last_error) VALUES(?,?,1,'reel-video-production','Active',?,?,NULL) ON CONFLICT(project_id) DO UPDATE SET agent_id=excluded.agent_id,active=1,stop_phase_key='reel-video-production',status='Active',updated_at=excluded.updated_at,last_error=NULL").bind(projectId,AGENT_ID,now,now).run()}
export async function assignments(db:any){
 await ensureAgentControlSchema(db);
 const rows=await db.prepare(`SELECT p.id,p.client,p.project_type_code AS projectType,p.stage,COALESCE(pr.phase_key,last.phase_key) AS phaseKey,COALESCE(pr.label,last.label,p.assignment_stage) AS phaseLabel,COALESCE(pr.status,last.status,p.phase_status) AS phaseStatus,COALESCE(ac.active,0) AS autopilotActive,COALESCE(ac.status,'Ready') AS autopilotStatus,ac.last_phase_key AS lastPhaseKey,ac.last_error AS lastError FROM projects p JOIN project_members pm ON pm.project_id=p.id AND pm.member_email=? LEFT JOIN phase_records pr ON pr.id=(SELECT id FROM phase_records WHERE project_id=p.id AND phase_key IN ('strategy-direction','monthly-direction','batch-ideas','content-production','reel-video-production') AND status!='Approved' ORDER BY position LIMIT 1) LEFT JOIN agent_project_controls ac ON ac.project_id=p.id AND ac.agent_id=? LEFT JOIN phase_records last ON last.project_id=p.id AND last.phase_key=ac.last_phase_key WHERE p.project_type_code IN ('Internal Social Account','Client Social Account') ORDER BY p.created_at`).bind(AGENT_ID,AGENT_ID).all();
 let lastSeenAt:string|null=null;
 try{const token=await db.prepare("SELECT last_used_at AS lastSeenAt FROM agent_api_tokens WHERE agent_id=? AND status='Active' AND revoked_at IS NULL ORDER BY created_at DESC LIMIT 1").bind(AGENT_ID).first<any>();lastSeenAt=token?.lastSeenAt||null}catch{}
 const presence=agentPresence(lastSeenAt),enriched=[];
 for(const row of rows.results as any[]){
  const parent=await db.prepare("SELECT id,status,last_error AS lastError FROM orchestrator_jobs WHERE project_id=? AND job_type='AGENT_TASK' ORDER BY created_at DESC LIMIT 1").bind(row.id).first<any>();
  const childRows=parent?.id?await db.prepare("SELECT job_type AS jobType,status FROM orchestrator_jobs WHERE parent_job_id=? ORDER BY created_at").bind(parent.id).all():{results:[]};
  const execution=summarizeAgentExecution({phaseStatus:row.phaseStatus,controlStatus:row.autopilotStatus,controlActive:Boolean(row.autopilotActive),lastError:parent?.lastError||row.lastError,parentStatus:parent?.status,children:childRows.results as any[]});
  enriched.push({...row,autopilotActive:Boolean(row.autopilotActive),automationEnabled:Boolean(row.autopilotActive),agentConnectionStatus:presence.state.toUpperCase(),agentConnectionLabel:presence.label,agentLastSeenAt:presence.lastSeenAt,executionStatus:execution.label,executionState:execution.state,needsAttention:execution.needsAttention,scopeCompleted:execution.scopeCompleted,autopilotStatus:execution.label});
 }
 return enriched.filter(row=>row.phaseKey&&(row.phaseStatus!=="Approved"||row.scopeCompleted));
}
