function preserveProductionReferenceSelections(payload:any,currentData:any){const currentItems=Array.isArray(currentData?.production_items)?currentData.production_items:[],nextItems=Array.isArray(payload?.production_items)?payload.production_items:[];for(const next of nextItems){const current=currentItems.find((item:any)=>String(item.contentId||item.content_id)===String(next.contentId||next.content_id));if(!current)continue;for(const nextAsset of Array.isArray(next.assets)?next.assets:[]){const number=Number(nextAsset.assetNumber||nextAsset.asset_number),currentAsset=(Array.isArray(current.assets)?current.assets:[]).find((asset:any)=>Number(asset.assetNumber||asset.asset_number)===number);if(!currentAsset)continue;if(Array.isArray(currentAsset.referenceTypes))nextAsset.referenceTypes=currentAsset.referenceTypes.map(String);if(number>1&&typeof currentAsset.continuityWithFirstImage==="boolean")nextAsset.continuityWithFirstImage=currentAsset.continuityWithFirstImage;if(currentAsset.visualPrompt?.referenceSwitches&&nextAsset.visualPrompt)nextAsset.visualPrompt.referenceSwitches={...currentAsset.visualPrompt.referenceSwitches};nextAsset.generationQuality=currentAsset.generationQuality==="high"?"high":currentAsset.generationQuality==="medium"?"medium":"low";nextAsset.generationResolution="1K";nextAsset.maxInputReferences=FRAMEFLOW_IMAGE_REFERENCE_LIMIT}}return payload}
