   if(continuityWithFirstImage){if(anchorArchitecture?.structuredAnchor.status!=="APPROVED")throw Object.assign(new Error(`Content ${contentIndex+1} Structured Anchor must be approved before visual ${assetNumber} can inherit it.`),{status:409,code:"STRUCTURED_ANCHOR_NOT_APPROVED"});approvedAnchor=await db.prepare("SELECT COALESCE(source.item_key,cur.item_key) AS itemKey,COALESCE(source.storage_key,cur.storage_key) AS storageKey,COALESCE(source.file_name,cur.file_name) AS fileName,COALESCE(source.mime_type,cur.mime_type) AS mimeType,COALESCE(source.size_bytes,cur.size_bytes) AS sizeBytes,COALESCE(source.version,cur.version) AS version,CASE WHEN source.id IS NOT NULL THEN 'approved-generation-source' ELSE 'current-approved-preview' END AS referenceVariant FROM visual_asset_revisions cur LEFT JOIN asset_upscale_jobs upscale ON upscale.derived_asset_id=cur.id AND upscale.status='UPSCALE_COMPLETED' LEFT JOIN visual_asset_revisions source ON source.id=upscale.source_asset_id WHERE cur.project_id=? AND cur.phase='content-production' AND cur.item_key=? AND cur.is_current=1 ORDER BY cur.version DESC LIMIT 1").bind(projectId,socialBatchAssetKey(batchId,`${contentId}-asset-1`)).first<any>();if(!approvedAnchor)throw Object.assign(new Error(`Content ${contentIndex+1} needs its approved Content Anchor Image before visual ${assetNumber} can be generated.`),{status:409,code:"FIRST_IMAGE_REFERENCE_MISSING"})}
