 await db.prepare("UPDATE projects SET phase_status='Reviewing',stage=?,assignment_stage=?,assignment_status='Awaiting Approval',approval_title=NULL,progress=? WHERE id=?").bind(`${phase.label} · Reviewing`,phase.label,progress,parent.projectId).run();
